import{_ as a,H as e,f as d,i as o}from"./chunks/framework.CBmkDW73.js";const _=JSON.parse('{"title":"철학","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/philosophy.md","filePath":"ko/guide/philosophy.md"}'),r={name:"ko/guide/philosophy.md"};function i(h,t,s,n,l,p){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="철학" tabindex="-1">철학 <a class="header-anchor" href="#철학" aria-label="Permalink to &quot;철학&quot;">​</a></h1><h2 id="지시가-아닌-의도" tabindex="-1">지시가 아닌 의도 <a class="header-anchor" href="#지시가-아닌-의도" aria-label="Permalink to &quot;지시가 아닌 의도&quot;">​</a></h2><p>에이전트에게 무엇을 달성해야 하는지, 완료가 어떤 모습인지를 말하라. 방법은 에이전트가 결정하게 하라.</p><p>단계별 지침은 에이전트가 똑똑해질수록 시대에 뒤떨어진다. 의도 선언은 항상 유효하다 — 그것이 담는 것은 <strong>무엇이 중요한가</strong>이지, <strong>어떻게 달성하는가</strong>가 아니다.</p><h2 id="가치-있을-때만-규율에-비용을-지불하라" tabindex="-1">가치 있을 때만 규율에 비용을 지불하라 <a class="header-anchor" href="#가치-있을-때만-규율에-비용을-지불하라" aria-label="Permalink to &quot;가치 있을 때만 규율에 비용을 지불하라&quot;">​</a></h2><p>트리아지가 결정한다. 오타 수정에는 명세가 필요 없다. 새 시스템에는 필요하다. Praxis는 복잡도에 비례하여 오버헤드를 적용한다.</p><table tabindex="0"><thead><tr><th>작업</th><th>Praxis 비용</th></tr></thead><tbody><tr><td>오타 수정 / 사소한 작업</td><td>~680토큰 (부트스트랩만)</td></tr><tr><td>소규모 작업 (<code>tdd</code>)</td><td>~1,270토큰</td></tr><tr><td>표준 기능 (<code>design</code>→<code>review</code>)</td><td>~3,600토큰</td></tr><tr><td>복잡한 작업 (<code>design</code>→<code>ship</code>)</td><td>~4,800토큰</td></tr></tbody></table><h2 id="스킬은-짧다" tabindex="-1">스킬은 짧다 <a class="header-anchor" href="#스킬은-짧다" aria-label="Permalink to &quot;스킬은 짧다&quot;">​</a></h2><p>규칙을 표현하는 데 3,000토큰이 필요하다면, 그것은 아마 규칙이 아니라 매뉴얼이다. Praxis 스킬은 간결하며 의도에 집중되어 있다 (스킬당 약 ~150~~1,180토큰).</p><p>짧은 스킬은 에이전트가 완전히 읽고 안정적으로 따르며, AI 능력이 발전해도 프레임워크가 유지 관리 가능하게 한다.</p><h2 id="명세는-사실이지-계획이-아니다" tabindex="-1">명세는 사실이지, 계획이 아니다 <a class="header-anchor" href="#명세는-사실이지-계획이-아니다" aria-label="Permalink to &quot;명세는 사실이지, 계획이 아니다&quot;">​</a></h2><p>명세는 결정 목록이다: 계약, 불변 조건, 실패 모드, 테스트 기준. 내러티브 없음, 이유 없음, 단계 없음. 계획은 별도이며 마일스톤 스텁 — 스크립트가 아니다.</p><p>에이전트는 도메인 지식을 가져온다. Praxis는 무엇을 결정해야 하는지에 대한 구조를 제공하지, 어떻게 결정하는지에 대한 지침이 아니다.</p>',13)])])}const u=a(r,[["render",i]]);export{_ as __pageData,u as default};
